function.arguments:
{"command": "cat > /app/cmd.sh << 'EOF'
#!/bin/bash
jq -n --slurp /app/users.json '[.[] | select(.status == "active") | {
  user_id: .id,
  username: .username,
  email: .email,
  last_login: (.last_login | split("T")[0]),
  role_count: (.roles | length),
  primary_role: (if (.roles | length) > 0 then .roles[0] else null end)
}] | sort_by(.username) | indent(2)' > /app/active_users_report.json
EOF
chmod +x /app/cmd.sh"}

